/**
 * frontend/src/components/Dashboard.jsx
 * VERSION FINALE - Propre et optimisée
 */

import React, { useState, useEffect } from 'react';
import { attendanceAPI, studentsAPI } from './api_service';

const COLORS = {
  primary: '#4F46E5',
  primaryLight: '#EEF2FF',
  red: '#FF0033',
  redLight: '#FFE6E6',
  green: '#00D4A5',
  greenLight: '#E6FFF8',
  textMain: '#1E293B',
  textMuted: '#64748B',
  border: '#E2E8F0',
  background: '#F8FAFC',
  surface: '#FFFFFF',
};

const Dashboard = ({ addNotification }) => {
  const [stats, setStats] = useState({
    active_students: 0,
    present_today: 0,
    absent_today: 0,
    total_records: 0,
    avg_confidence: 0,
    max_confidence: 0,
    min_confidence: 0,
  });

  const [attendanceLog, setAttendanceLog] = useState([]);
  const [statusList, setStatusList] = useState([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState(null);
  const [lastUpdated, setLastUpdated] = useState(null);
  const [showAll, setShowAll] = useState(false);

  const deepExtract = (res, fallbackKey = null) => {
    if (!res) return {};
    let data = res.data || res;
    if (data.success && data.data) data = data.data;
    if (data.success && data.data) data = data.data;
    return fallbackKey ? (data[fallbackKey] || data) : data;
  };

  const loadData = async () => {
    try {
      setError(null);
      setLoading(true);

      const [studentRes, attendanceRes, logRes, statusRes] = await Promise.all([
        studentsAPI.getStats(),
        attendanceAPI.getStats(),
        attendanceAPI.getTodayLog(),
        attendanceAPI.getStatus(),
      ]);

      const studentData = deepExtract(studentRes);
      const attendanceData = deepExtract(attendanceRes);
      let logData = deepExtract(logRes, 'records') || [];
      const statusData = deepExtract(statusRes, 'students') || [];

      // Correction importante : Si le log est vide mais qu'on a des présents dans status
      const activeStudents = Number(studentData.active_students) || 0;
      let presentToday = Number(deepExtract(statusRes).present_today) || 0;

      // Fallback : calculer à partir des logs si status ne donne rien
      if (presentToday === 0 && logData.length > 0) {
        presentToday = new Set(logData.map(r => r.student_id || r.id).filter(Boolean)).size;
      }

      setStats({
        active_students: activeStudents,
        present_today: presentToday,
        absent_today: Math.max(0, activeStudents - presentToday),
        total_records: Number(attendanceData.total_records) || logData.length,
        avg_confidence: Number(attendanceData.avg_confidence) || 0,
        max_confidence: Number(attendanceData.max_confidence) || 0,
        min_confidence: Number(attendanceData.min_confidence) || 0,
      });

      setAttendanceLog(Array.isArray(logData) ? logData : []);
      setStatusList(Array.isArray(statusData) ? statusData : []);

      setLastUpdated(new Date().toLocaleTimeString('fr-FR', { 
        hour: '2-digit', minute: '2-digit', second: '2-digit' 
      }));

    } catch (err) {
      console.error(err);
      setError("Erreur lors du chargement des données");
      if (addNotification) addNotification("Erreur de chargement du dashboard", "error");
    } finally {
      setLoading(false);
    }
  };

  const handleRefresh = async () => {
    setRefreshing(true);
    await loadData();
    setRefreshing(false);
  };

  useEffect(() => {
    loadData();
  }, []);

  if (loading) return <div style={styles.loading}>Chargement...</div>;

  return (
    <div style={styles.container}>
      <div style={styles.header}>
        <div>
          <h2 style={styles.title}>Tableau de Bord</h2>
          <p style={styles.subtitle}>
            Suivi des présences en temps réel • Dernière mise à jour : {lastUpdated || '—'}
          </p>
        </div>
        <button onClick={handleRefresh} style={styles.refreshBtn} disabled={refreshing}>
          {refreshing ? 'Actualisation...' : 'Actualiser'}
        </button>
      </div>

      {/* Stats Cards */}
      <div style={styles.statsGrid}>
        <StatCard label="Étudiants inscrits" value={stats.active_students} accent={COLORS.primary} />
        <StatCard label="Présents aujourd'hui" value={stats.present_today} accent={COLORS.green} />
        <StatCard label="Absents aujourd'hui" value={stats.absent_today} accent={COLORS.red} />
        <StatCard 
          label="Taux de présence" 
          value={stats.active_students > 0 ? `${((stats.present_today / stats.active_students) * 100).toFixed(1)}%` : '0%'} 
          accent={stats.present_today / stats.active_students >= 0.8 ? COLORS.green : COLORS.red}
        />
      </div>

      <div style={styles.mainGrid}>
        {/* Derniers scans */}
        <div style={styles.section}>
          <h3 style={styles.sectionTitle}>Derniers scans aujourd’hui</h3>
          {attendanceLog.length === 0 ? (
            <div style={styles.emptyState}>Aucune présence enregistrée aujourd’hui.</div>
          ) : (
            <div role="table" style={styles.table}>
              <div style={styles.tableHeader}>
                <div style={{ flex: 2 }}>Étudiant</div>
                <div style={{ flex: 1 }}>Confiance</div>
                <div style={{ flex: 1 }}>Heure</div>
              </div>
              {attendanceLog.slice(0, showAll ? undefined : 10).map((record, i) => (
                <div key={i} style={styles.tableRow}>
                  <div style={{ flex: 2, fontWeight: 500 }}>{record.student || record.name || 'Inconnu'}</div>
                  <div style={{ flex: 1 }}><ConfidenceBadge confidence={record.confidence} /></div>
                  <div style={{ flex: 1, color: COLORS.textMuted }}>
                    {record.timestamp ? new Date(record.timestamp).toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' }) : '—'}
                  </div>
                </div>
              ))}
            </div>
          )}
          <div style={styles.tableInfo}>
            Total aujourd’hui : {attendanceLog.length} scans
            {attendanceLog.length > 10 && (
              <button onClick={() => setShowAll(!showAll)} style={styles.viewMoreBtn}>
                {showAll ? "Voir moins" : "Voir plus"}
              </button>
            )}
          </div>
        </div>

        {/* Analyse du pipeline */}
        <div style={styles.section}>
          <h3 style={styles.sectionTitle}>Analyse du pipeline</h3>
          <div style={styles.summaryBox}>
            <SummaryItem label="Total scans aujourd’hui" value={stats.total_records} color={COLORS.primary} />
            <SummaryItem label="Précision moyenne" value={stats.avg_confidence ? `${(stats.avg_confidence * 100).toFixed(1)}%` : 'N/A'} color={COLORS.green} />
            <SummaryItem label="Meilleure précision" value={stats.max_confidence ? `${(stats.max_confidence * 100).toFixed(1)}%` : 'N/A'} color={COLORS.green} />
            <SummaryItem label="Précision minimale" value={stats.min_confidence ? `${(stats.min_confidence * 100).toFixed(1)}%` : 'N/A'} color={COLORS.red} />
          </div>
        </div>
      </div>

      {/* Liste des étudiants */}
      <div style={styles.section}>
        <h3 style={styles.sectionTitle}>Liste des étudiants</h3>
        <div role="table" style={styles.table}>
          <div style={styles.tableHeader}>
            <div style={{ flex: 2 }}>Nom</div>
            <div style={{ flex: 2 }}>Email</div>
            <div style={{ flex: 1 }}>Statut</div>
          </div>
          {statusList.map((student, index) => (
            <div key={student.student_id || index} style={styles.tableRow}>
              <div style={{ flex: 2, fontWeight: 500 }}>{student.name}</div>
              <div style={{ flex: 2, color: COLORS.textMuted }}>{student.email || '—'}</div>
              <div style={{ flex: 1 }}><StatusBadge present={!!student.present} /></div>
            </div>
          ))}
        </div>
        <div style={styles.tableInfo}>
          Total : {statusList.length} étudiants • {statusList.filter(s => s.present).length} présents
        </div>
      </div>
    </div>
  );
};

// ==================== SOUS-COMPOSANTS ====================
const StatCard = ({ label, value, accent }) => (
  <div style={{
    ...styles.statCard,
    borderLeft: `6px solid ${accent}`,
    boxShadow: `0 4px 15px ${accent}20`
  }}>
    <p style={styles.statLabel}>{label}</p>
    <p style={{...styles.statValue, color: accent}}>{value}</p>
  </div>
);

const ConfidenceBadge = ({ confidence = 0 }) => {
  const score = Number(confidence);
  const perc = (score * 100).toFixed(0);
  let color = COLORS.red, bg = COLORS.redLight;
  if (score > 0.7) { color = COLORS.green; bg = COLORS.greenLight; }
  else if (score > 0.4) { color = COLORS.primary; bg = COLORS.primaryLight; }

  return (
    <span style={{ padding: '6px 14px', backgroundColor: bg, color, borderRadius: '9999px', fontWeight: 700, fontSize: '0.85rem' }}>
      {perc}%
    </span>
  );
};

const StatusBadge = ({ present }) => (
  <span style={{
    padding: '7px 18px',
    backgroundColor: present ? COLORS.greenLight : COLORS.redLight,
    color: present ? '#0A7A5E' : '#C53030',
    borderRadius: '9999px',
    fontWeight: 700
  }}>
    {present ? 'PRÉSENT' : 'ABSENT'}
  </span>
);

const SummaryItem = ({ label, value, color }) => (
  <div style={styles.summaryItem}>
    <p style={styles.summaryLabel}>{label}</p>
    <p style={{...styles.summaryValue, color}}>{value}</p>
  </div>
);

